buildly-completo.html:
/* ══════════════════════════════════════════════════════════════
   DESKTOP — acima de 900px o app deixa de ser uma coluna de 480px
   (tamanho de celular) e passa a ocupar a tela. Abaixo disso nada
   muda: no iPhone continua exatamente como sempre foi.
   Os !important existem porque vários cabeçalhos fixos trazem o
   max-width:480px em style inline, que só perde para !important.
   ══════════════════════════════════════════════════════════════ */
@media (min-width: 900px) {
  body { max-width: 1100px; }
  .hdr, .tabs, #obra-scroll-body { max-width: 1100px !important; }
  /* 5 colunas de botões aproveitam a largura sem esticar os cards */
  .home-grid { grid-template-columns: repeat(5, 1fr); gap: 14px; padding: 12px 16px 0; }
  /* Os apps em iframe têm cabeçalho próprio; sobra mais altura útil */
  .page iframe { height: calc(100vh - 76px) !important; }
  /* Sem o padding lateral, o iframe recebe a largura cheia da página. Com
     ele, o app de dentro ficava 32px mais estreito que o de fora e, numa
     janela de ~900px, caía abaixo do limite de desktop: o app externo
     virava desktop e o de dentro continuava no formato de celular. */
  #page-rdo, #page-custos, #page-reuniao, #page-resumo-tempo,
  #page-medicao, #page-documentos, #page-manutencao { padding: 0; }
  /* Kanban do Check-in: as 4 colunas lado a lado em vez de empilhadas */
  #checkin-kanban-checkin { flex-direction: row; align-items: flex-start; gap: 12px; }
  #checkin-kanban-checkin > .kol { flex: 1; min-width: 0; }
  /* Obras, Pautas e Check-in seguem a mesma regra dos outros apps: os
     blocos acompanham a largura das abas, e quem ganha limite é o campo
     de digitação. Assim toda tela do app fecha na mesma coluna. */
  #obra-scroll-body { padding: 16px 0; }
  #obra-scroll-body .sec,
  #page-pauta .sec,
  #page-checkin .sec { margin-left: 16px; margin-right: 16px; }
  /* O cadastro da Obra tem muitos campos: em duas colunas a tela deixa
     de ser uma fila comprida com metade da largura vazia, e o formulário
     inteiro fecha na mesma borda à direita. */
  #obra-scroll-body .sec { display: grid; grid-template-columns: 1fr 1fr; gap: 0 18px; align-content: start; }
  #obra-scroll-body .sec-title,
  #obra-scroll-body .frow-2,
  #obra-scroll-body .btn-full { grid-column: 1 / -1; }
  #obra-scroll-body .sec input,
  #obra-scroll-body .sec textarea,
  #obra-scroll-body .sec select { max-width: none; }
  /* A seção do logo não é um formulário de campos: são a miniatura e dois
     botões que andam juntos. Na grade eles se separavam em células
     diferentes, então essa seção fica fora dela. */
  #obra-scroll-body .sec:has(#obra-logo-preview) { display: block; }
  #page-pauta input:not([type="checkbox"]):not([type="radio"]),
  #page-pauta textarea,
  #page-pauta select,
  #page-checkin input:not([type="checkbox"]):not([type="radio"]),
  #page-checkin textarea,
  #page-checkin select { max-width: 660px; }
  /* Modais continuam estreitos de propósito: caixa de diálogo larga
     demais atrapalha em vez de ajudar */
  .modal { max-width: 560px; }
}

rdo.html:
/* ══════════════════════════════════════════════════════════════
   DESKTOP — acima de 900px o app deixa de ser uma coluna de 480px
   (tamanho de celular) e passa a ocupar a tela. Abaixo disso nada
   muda: no celular continua exatamente como sempre foi.
   ══════════════════════════════════════════════════════════════ */
/* 860 e nao 900: o iframe pode ficar alguns pixels mais estreito que a
   janela (barra de rolagem, bordas). Com o mesmo numero dos dois lados,
   o app de dentro corria o risco de continuar em formato de celular
   enquanto o de fora ja estava em desktop. */
@media (min-width: 860px) {
  body { max-width: 1100px; }
  .topbar, .header, .tabs { max-width: 1100px !important; }
  /* Conteúdo em duas colunas: com 1100px de largura, um campo de
     texto sozinho na linha fica ruim de ler e de preencher */
  .view.active {
    display: grid;
    /* auto-fit: com várias seções vira duas colunas; com uma só, ela
       ocupa a linha inteira em vez de deixar metade da tela vazia */
    grid-template-columns: repeat(auto-fit, minmax(430px, 1fr));
    gap: 0 14px;
    align-items: start;
  }
  /* O conteúdo acompanha a largura da barra de abas e do cabeçalho:
     as três bordas se alinham na mesma coluna, e é isso que dá a
     sensação de peça inteira em vez de blocos soltos no meio da tela. */
  .view.active > * { max-width: none; }
  /* O campo de digitação é que ganha limite, não o cartão: texto muito
     largo cansa a leitura e a mão viaja demais até o fim da linha.
     Em duas colunas o campo já é menor que isso, então nada muda lá. */
  .view.active input:not([type="checkbox"]):not([type="radio"]),
  .view.active textarea,
  .view.active select { max-width: 660px; }
  /* Modais continuam estreitos de propósito */
  .modal { max-width: 560px; }
  /* A visualização do PDF ocupa a tela toda, fora da grade */
  #pdfOverlay { max-width: none; }
}

